/* ══════════════════════════════════════════
   SVF Homes – Ambattur A2B
   Stacked Page Navigation
══════════════════════════════════════════ */

const pages    = document.querySelectorAll('.stack-page');
const navDots  = document.getElementById('navDots');
const dots     = document.querySelectorAll('.dot');
const navPills = document.querySelectorAll('.page-header .nav-pill[data-page]');

let currentPage = 0;  // 0 = landing
const HEADER_H  = 72; // sticky header height

/* ─────────────────────────────────────────
   Core: navigate to a section by scrolling
───────────────────────────────────────── */
function goTo(index) {
  const target = pages[index];
  if (!target) return;

  currentPage = index;
  const top = target.getBoundingClientRect().top + window.scrollY - (index === 0 ? 0 : HEADER_H);
  window.scrollTo({ top: Math.max(0, top), behavior: 'smooth' });

  updateDots();
}

/* ─────────────────────────────────────────
   "Explore" → go to About (section 1)
───────────────────────────────────────── */
function openSections() {
  goTo(1);
}

/* ─────────────────────────────────────────
   Back to Landing (scroll to top)
───────────────────────────────────────── */
function backToLanding() {
  goTo(0);
}

/* ─────────────────────────────────────────
   Update nav dots + header pills
───────────────────────────────────────── */
function updateDots() {
  dots.forEach((dot, i) => {
    dot.classList.toggle('active', i + 1 === currentPage);
  });
  navPills.forEach(pill => {
    pill.classList.toggle('current', Number(pill.dataset.page) === currentPage);
  });
}

/* ─────────────────────────────────────────
   Scroll spy — track which section is in
   view and show the dots past the landing
───────────────────────────────────────── */
function updateScrollSpy() {
  const probe = window.scrollY + window.innerHeight * 0.4;
  let idx = 0;
  pages.forEach(page => {
    if (page.offsetTop <= probe) idx = Number(page.dataset.index);
  });
  if (idx !== currentPage) {
    currentPage = idx;
    updateDots();
  }
  navDots.classList.toggle('visible', window.scrollY > window.innerHeight * 0.5);
}

window.addEventListener('scroll', updateScrollSpy, { passive: true });
window.addEventListener('resize', updateScrollSpy, { passive: true });
updateScrollSpy();

/* ─────────────────────────────────────────
   Floor Plan Tab Switch
───────────────────────────────────────── */
function switchPlan(btn, planId) {
  document.querySelectorAll('.plan-tab').forEach(t => t.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.plan-content').forEach(p => p.classList.remove('active'));
  const target = document.getElementById(planId);
  if (target) {
    target.classList.add('active');

    // Reset the newly shown plan to 2D view
    const area = target.querySelector('.plan-image-area');
    if (area) {
      const viewBtns = area.querySelectorAll('.view-btn');
      viewBtns.forEach(b => b.classList.remove('active'));
      if (viewBtns[0]) viewBtns[0].classList.add('active'); // activate 2D button

      const imgs = area.querySelectorAll('.plan-image-frame img');
      if (imgs.length >= 2) {
        imgs[0].style.display = 'block';  // show 2D
        imgs[1].style.display = 'none';   // hide 3D
      }

      // Reset download link to 2D
      const dlAnchor = area.querySelector('.btn-download-plan');
      const firstImg = area.querySelector('.plan-image-frame img');
      if (dlAnchor && firstImg) {
        const bhk   = planId.includes('2bhk') ? '2BHK' : '3BHK';
        dlAnchor.href     = firstImg.getAttribute('src');
        dlAnchor.download = `SVF_A2B_${bhk}_2D_FloorPlan.png`;
      }
    }
  }
}

/* ─────────────────────────────────────────
   Floor Plan View Toggle (2D ↔ 3D)
───────────────────────────────────────── */
function switchView(btn, showImgId) {
  const area = btn.closest('.plan-image-area');
  if (!area) return;

  area.querySelectorAll('.view-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');

  const frame = area.querySelector('.plan-image-frame');
  frame.querySelectorAll('img').forEach(img => {
    img.style.display = img.id === showImgId ? 'block' : 'none';
  });

  // Update the download anchor to match the visible image
  const visibleImg = frame.querySelector(`#${showImgId}`);
  const dlAnchor   = area.querySelector('.btn-download-plan');
  if (dlAnchor && visibleImg) {
    const is3d  = showImgId.includes('3d');
    const bhk   = showImgId.includes('2bhk') ? '2BHK' : '3BHK';
    const fname = `SVF_A2B_${bhk}_${is3d ? '3D' : '2D'}_FloorPlan.png`;
    dlAnchor.href     = visibleImg.getAttribute('src');
    dlAnchor.download = fname;
  }
}

/* ─────────────────────────────────────────
   Download a file — reads as arraybuffer,
   creates a Blob URL, triggers save dialog.
   Works on both file:// and http://.
───────────────────────────────────────── */
function downloadFile(src, filename) {
  var xhr = new XMLHttpRequest();
  xhr.open('GET', src, true);
  xhr.responseType = 'blob';
  xhr.onload = function () {
    var blob = xhr.response;
    var url  = URL.createObjectURL(blob);

    var a        = document.createElement('a');
    a.href       = url;
    a.download   = filename;
    a.style.display = 'none';
    document.body.appendChild(a);
    a.click();

    // Clean up
    setTimeout(function () {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 5000);
  };
  xhr.onerror = function () {
    // Native anchor downloads are used by the page links, including when opened locally.
    // Do not open the file in a new tab as a fallback.
    console.warn('Download request failed; use the native download link instead.');
  };
  xhr.send();
}


/* Direct index.html support: local file:// pages cannot reliably fetch sibling assets
   for Blob downloads. Embedded data URLs let the download links save files directly. */
const embeddedDownloadData = {
  'Floor_Plan_2D.png': 'data:image/png;base64,',
  'Floor_Plan_3D.png': 'data:image/png;base64,',
  'Brouchure.jpeg': 'data:image/jpeg;base64,'
};

document.addEventListener('click', function (event) {
  const link = event.target.closest('a.btn-download-plan, a.btn-download');
  if (!link || window.location.protocol !== 'file:') return;
  const assetName = (link.getAttribute('href') || '').split('/').pop();
  const dataUrl = embeddedDownloadData[assetName];
  if (!dataUrl) return;
  event.preventDefault();
  const downloadLink = document.createElement('a');
  downloadLink.href = dataUrl;
  downloadLink.download = link.getAttribute('download') || assetName;
  document.body.appendChild(downloadLink);
  downloadLink.click();
  downloadLink.remove();
});

/* ─────────────────────────────────────────
   Keyboard — Escape closes the lightbox
   or returns to the landing hero
───────────────────────────────────────── */
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    const lightbox = document.getElementById('smartLightbox');
    if (lightbox && lightbox.classList.contains('open')) {
      closeSmartLightbox();
    } else {
      backToLanding();
    }
  }
});

/* ─────────────────────────────────────────
   Smart Living Device Switcher
───────────────────────────────────────── */
const smartDevices = ['smart-door', 'smart-light', 'smart-fan', 'smart-water-tank'];
let currentSmartIndex = 0;

function switchSmartDevice(deviceId) {
  const index = smartDevices.indexOf(deviceId);
  if (index === -1) return;
  currentSmartIndex = index;
  updateSmartView();
}

function prevSmartDevice() {
  currentSmartIndex = (currentSmartIndex - 1 + smartDevices.length) % smartDevices.length;
  updateSmartView();
}

function nextSmartDevice() {
  currentSmartIndex = (currentSmartIndex + 1) % smartDevices.length;
  updateSmartView();
}

function updateSmartView() {
  const activeId = smartDevices[currentSmartIndex];

  // Update tabs
  document.querySelectorAll('.smart-tab').forEach((tab) => {
    tab.classList.toggle('active', tab.getAttribute('data-device') === activeId);
  });

  // Update image wrappers
  document.querySelectorAll('.smart-img-wrapper').forEach((wrapper) => {
    wrapper.classList.toggle('active', wrapper.id === `img-${activeId}`);
  });

  // Update detail view panels
  document.querySelectorAll('.smart-device-view').forEach((view) => {
    view.classList.toggle('active', view.id === `view-${activeId}`);
  });

  // Update index counter
  const counterEl = document.getElementById('smartCurrentIdx');
  if (counterEl) counterEl.textContent = currentSmartIndex + 1;
}

function openSmartLightbox(imgSrc, title) {
  const lightbox = document.getElementById('smartLightbox');
  const lbImg = document.getElementById('smartLightboxImg');
  const lbCaption = document.getElementById('smartLightboxCaption');
  if (!imgSrc) {
    const activeImg = document.querySelector('.smart-img-wrapper.active img');
    if (activeImg) {
      imgSrc = activeImg.getAttribute('src');
      title = activeImg.getAttribute('alt');
    }
  }
  if (lightbox && lbImg) {
    lbImg.src = imgSrc || 'smart-door.png';
    if (lbCaption) lbCaption.textContent = title || 'Smart Device Preview';
    lightbox.classList.add('open');
  }
}

function closeSmartLightbox() {
  const lightbox = document.getElementById('smartLightbox');
  if (lightbox) lightbox.classList.remove('open');
}

/* ─────────────────────────────────────────
   Autoplay video (with static image fallback)
───────────────────────────────────────── */
document.addEventListener('DOMContentLoaded', () => {
  const vid = document.getElementById('bgVideo');
  if (vid && vid.tagName === 'VIDEO') {
    vid.play().catch(() => {
      // Browser blocked autoplay — video stays paused but still shows first frame
    });
  }
});
